-- Two-factor authentication with a TOTP authenticator app. The secrets are encrypted with app.encryption-key.
alter table users
    add column totp_secret         text,
    -- Generated by the setup and kept until the first code confirms it
    add column totp_pending_secret text,
    -- The last accepted time step, so that a code cannot be used twice
    add column totp_last_step      bigint,
    add column totp_enabled_at     timestamp(6) with time zone;

-- One-time codes for signing in without the authenticator; only their hashes are stored.
create table recovery_codes
(
    id         bigint generated always as identity primary key,
    user_id    bigint      not null references users (id) on delete cascade,
    code_hash  varchar(64) not null,
    used_at    timestamp(6) with time zone,
    created_at timestamp(6) with time zone not null default now()
);

create index idx_recovery_codes_user on recovery_codes (user_id);

-- Browsers where the code is not asked again; the cookie holds the token, the table its hash.
create table trusted_devices
(
    id           bigint generated always as identity primary key,
    user_id      bigint      not null references users (id) on delete cascade,
    token_hash   varchar(64) not null unique,
    expires_at   timestamp(6) with time zone not null,
    created_at   timestamp(6) with time zone not null default now()
);

create index idx_trusted_devices_user on trusted_devices (user_id);
